(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-292":{scenario:{company:"Vạn Xuân Packaging Solutions",supervisor:{name:"Ông Thanh Tùng",role:{vi:"Giám đốc Khách hàng Chiến lược",en:"Head of Strategic Accounts"}},ref_code:"KA-7740",title:{vi:"Đúng cam kết. Đúng công thức. Đúng bảo mật.",en:"Right volume. Right formula. Right confidentiality."},brief:{vi:"Bạn chuẩn bị phụ lục gia hạn hợp đồng 2027 KA-7740 cung cấp thùng carton cho một nhà máy nước giải khát. Khách đã xác nhận bằng văn bản dự báo 2,4 triệu thùng; dòng sản phẩm mới thêm 0,8 triệu thùng chưa được duyệt, chưa có thư cam kết. Bậc khối lượng: TIER-1 dưới 2 triệu, TIER-2 từ 2 đến dưới 3 triệu, TIER-3 từ 3 triệu. Giá cơ sở 4200 đồng/thùng; chỉ số giá giấy tăng từ 820 lên 943 USD/tấn. Sửa bậc khối lượng và đơn giá mới, rồi lập báo cáo có căn cứ.",en:"You are preparing the 2027 renewal addendum KA-7740 for supplying cartons to a beverage plant. The client confirmed a 2.4 million carton forecast in writing; a new product line would add 0.8 million but is not approved and has no letter of intent. Volume tiers: TIER-1 below 2 million, TIER-2 from 2 to below 3 million, TIER-3 from 3 million. Base price 4200 VND per carton; the paper index rose from 820 to 943 USD per ton. Correct the volume tier and the new unit price, then write an evidence-based report."},reference_title:{vi:"Hợp đồng khung & phụ lục cơ chế giá đã duyệt · KA-7740",en:"Approved framework contract & pricing mechanism annex · KA-7740"},fields:[{id:"VOL_TIER",label:{vi:"Bậc khối lượng năm 2027",en:"2027 volume tier"},initial:"TIER-3",expected:"TIER-2",choices:["TIER-1","TIER-2","TIER-3"],reference:"Biên bản xác nhận dự báo khối lượng",hint:{vi:"Chỉ khối lượng khách đã cam kết bằng văn bản mới được dùng để xác định bậc.",en:"Only volume committed in writing by the client may set the tier."}},{id:"UNIT_PRICE",label:{vi:"Đơn giá mới (VND/thùng)",en:"New unit price (VND/carton)"},initial:"4637",expected:"4486",reference:"Phụ lục cơ chế điều chỉnh giá",ref_value:{vi:"Giá cơ sở 4200 đồng/thùng; chỉ số giá giấy kỳ gốc 820, kỳ điều chỉnh 943 USD/tấn",en:"Base price 4200 VND/carton; paper index base 820, adjustment period 943 USD/ton"},hint:{vi:"Bản nháp chuyển toàn bộ mức tăng chỉ số vào giá và dùng chiết khấu của bậc chưa đạt.",en:"The draft passes the full index rise into price and uses the discount of an unearned tier."}}],sop32:{vi:"Đơn giá mới = giá cơ sở x (1 + 60% x mức thay đổi chỉ số giá giấy) x (1 - chiết khấu bậc); chỉ điều chỉnh khi chỉ số đổi quá 5%. Chiết khấu TIER-1 0%, TIER-2 2%, TIER-3 4%; làm tròn đến đồng (mô phỏng).",en:"New price = base price x (1 + 60% x paper index change) x (1 - tier discount); adjust only if the index moves over 5%. Discounts TIER-1 0%, TIER-2 2%, TIER-3 4%; round to the dong (training)."},context:{label:"KAM / KA-7740",metrics:[{label:{vi:"Dự báo đã xác nhận",en:"Confirmed forecast"},value:"2,400,000"},{label:{vi:"Khối lượng chưa cam kết",en:"Uncommitted volume"},value:"800,000"},{label:{vi:"Giá cơ sở",en:"Base price"},value:"4,200 VND"},{label:{vi:"Chỉ số giá giấy",en:"Paper index"},value:"820 / 943 USD/t"}]},crisis:{vi:"Trưởng phòng mua hàng của khách gợi ý: “Anh gửi tôi bảng giá và sản lượng bên anh đang bán cho đối thủ của chúng tôi để tham chiếu, tôi ký gia hạn ngay trong tuần.”",en:"The client's procurement head suggests: “Send me the prices and volumes you sell to our competitor as a benchmark, and I will sign the renewal this week.”"},options:{safe:{vi:"Từ chối cung cấp thông tin bảo mật của khách hàng khác, báo Giám đốc Khách hàng Chiến lược; đề xuất tham chiếu hợp lệ bằng chỉ số giá giấy công khai và phân tích chi phí của chính hợp đồng.",en:"Refuse to share another client's confidential data and inform the Head of Strategic Accounts; offer a lawful benchmark using the public paper index and this contract's own cost analysis."},shortcut:{vi:"Gửi bảng giá của khách hàng kia nhưng xóa tên để giữ được hợp đồng lớn.",en:"Send the other client's price list with the name removed to keep the big contract."},wait:{vi:"Không phản hồi khách và để phụ lục gia hạn treo đến khi khách đổi ý.",en:"Do not respond and leave the renewal pending until the client changes its mind."}},questions:{vi:["Vì sao hợp đồng 2027 áp dụng TIER-2 chứ không phải TIER-3? Văn bản nào chứng minh khối lượng cam kết?","Trình bày cách tính đơn giá theo cơ chế chỉ số và rủi ro pháp lý khi tiết lộ thông tin của khách hàng khác."],en:["Why does the 2027 contract use TIER-2 instead of TIER-3? Which document proves the committed volume?","Explain the index-linked price calculation and the legal risk of disclosing another client's information."]},hints:{vi:["Đặt bản nháp cạnh biên bản xác nhận dự báo, tách phần đã cam kết khỏi phần còn chờ duyệt.","Tính theo SOP mục 3.2: mức thay đổi chỉ số, tỷ lệ chuyển giá, rồi chiết khấu của bậc đúng.","Đọc lại SOP mục 4.2: thông tin giá của khách hàng khác là bí mật kinh doanh, mọi yêu cầu phải báo cáo."],en:["Place the draft next to the forecast confirmation and separate committed from pending volume.","Compute per SOP 3.2: index change, pass-through rate, then the correct tier discount.","Re-read SOP 4.2: other clients' prices are trade secrets and any request must be escalated."]}},learning:{summary:{vi:"Chuyên viên quản trị khách hàng chiến lược (KAM) phụ trách một số ít khách hàng lớn mang lại phần lớn doanh thu: xây dựng kế hoạch khách hàng nhiều năm, quản lý quan hệ nhiều tầng, đàm phán hợp đồng khung, giá và cơ chế điều chỉnh giá, theo dõi mức độ dịch vụ và mở rộng cơ hội hợp tác. Nghề đòi hỏi hiểu sâu chuỗi giá trị của khách, năng lực phân tích thương mại, đàm phán cân bằng và giữ bảo mật thông tin tuyệt đối.",en:"A key account manager looks after a few large clients that generate most of the revenue: building multi-year account plans, managing relationships at several levels, negotiating framework contracts, prices and price adjustment mechanisms, tracking service levels and expanding the partnership. The role needs deep insight into the client's value chain, commercial analysis, balanced negotiation and strict confidentiality."},responsibilities:{vi:["Lập kế hoạch khách hàng nhiều năm và sơ đồ các bên liên quan từ vận hành đến ban giám đốc.","Đàm phán hợp đồng khung, giá, bậc khối lượng và cơ chế điều chỉnh theo chỉ số nguyên liệu.","Điều phối sản xuất, chất lượng, giao hàng nội bộ để đạt cam kết mức độ dịch vụ.","Chủ trì họp đánh giá kinh doanh định kỳ (QBR) với khách hàng.","Theo dõi lợi nhuận, công nợ, rủi ro và cơ hội mở rộng của từng khách hàng chiến lược."],en:["Build multi-year account plans and stakeholder maps from operations to the board.","Negotiate framework contracts, prices, volume tiers and raw-material index adjustments.","Coordinate internal production, quality and delivery to meet service level commitments.","Lead quarterly business reviews (QBR) with the client.","Track profit, receivables, risks and growth opportunities for each strategic account."]},competencies:[{name:{vi:"Hoạch định khách hàng",en:"Account planning"},desc:{vi:"Phân tích chiến lược của khách, xác định mục tiêu chung và lộ trình tăng trưởng nhiều năm.",en:"Analyze the client's strategy, set shared goals and a multi-year growth roadmap."}},{name:{vi:"Đàm phán thương mại",en:"Commercial negotiation"},desc:{vi:"Đàm phán dựa trên dữ liệu chi phí, giá trị và điều khoản cân bằng rủi ro hai bên.",en:"Negotiate on cost and value data with terms that balance both sides' risks."}},{name:{vi:"Phân tích lợi nhuận khách hàng",en:"Account profitability"},desc:{vi:"Tính biên lợi nhuận theo khách, tác động của chiết khấu, điều chỉnh giá và chi phí phục vụ.",en:"Compute margin per client and the effect of discounts, price changes and cost to serve."}},{name:{vi:"Điều phối liên chức năng",en:"Cross-functional coordination"},desc:{vi:"Kéo sản xuất, chất lượng, kho vận, tài chính cùng giữ cam kết với khách.",en:"Align production, quality, logistics and finance behind client commitments."}},{name:{vi:"Bảo mật & liêm chính",en:"Confidentiality & integrity"},desc:{vi:"Không tiết lộ thông tin khách hàng khác, không trao đổi lợi ích cá nhân với người mua.",en:"Never disclose other clients' data or trade personal benefits with buyers."}}],knowledge:{vi:["Luật Thương mại 2005 về hợp đồng mua bán hàng hóa; mức phạt vi phạm tối đa 8% giá trị phần nghĩa vụ bị vi phạm.","Bộ luật Dân sự 2015 về giao kết, sửa đổi hợp đồng và hoàn cảnh thay đổi cơ bản.","Bảo vệ bí mật kinh doanh theo Luật Sở hữu trí tuệ và điều khoản bảo mật trong hợp đồng.","Cơ chế giá theo chỉ số nguyên liệu: kỳ gốc, ngưỡng kích hoạt, tỷ lệ chuyển giá, chu kỳ điều chỉnh.","Chỉ số mức độ dịch vụ OTIF, tỷ lệ lỗi chất lượng và thời gian xử lý khiếu nại."],en:["Commercial Law 2005 on sale of goods contracts; contractual penalties capped at 8% of the breached obligation.","Civil Code 2015 on contract formation, amendment and fundamental change of circumstances.","Trade secret protection under the Intellectual Property Law and contract confidentiality clauses.","Index-linked pricing: base period, trigger threshold, pass-through rate and adjustment cycle.","Service level metrics: OTIF, quality defect rate and complaint resolution time."]},tools:["Hệ thống CRM","Bảng tính mô hình giá","BI lợi nhuận khách hàng","Hệ thống ERP đơn hàng","Cổng hợp tác nhà cung cấp"],kpis:{vi:["Tỷ lệ gia hạn hợp đồng và giữ chân khách hàng chiến lược.","Tăng trưởng doanh thu từ nhóm khách hàng chiến lược.","Biên lợi nhuận gộp theo từng khách hàng.","Tỷ lệ giao hàng đúng hạn, đủ số lượng (OTIF)."],en:["Contract renewal and strategic account retention rate.","Revenue growth from strategic accounts.","Gross margin per account.","On-time in-full delivery rate (OTIF)."]},day:[{time:"08:30",vi:"Xem báo cáo OTIF, khiếu nại chất lượng và đơn hàng gấp của các khách chiến lược.",en:"Review OTIF, quality complaints and urgent orders for strategic accounts."},{time:"10:00",vi:"Chủ trì QBR với khách: kết quả quý, kế hoạch sản phẩm mới, cải tiến bao bì.",en:"Lead a client QBR: quarterly results, new products and packaging improvements."},{time:"13:30",vi:"Cập nhật mô hình giá theo chỉ số giấy và kiểm tra biên lợi nhuận phụ lục mới.",en:"Update the paper-index price model and check the new addendum's margin."},{time:"15:30",vi:"Họp nội bộ với sản xuất, kho vận về năng lực đáp ứng mùa cao điểm.",en:"Meet production and logistics on peak-season capacity."},{time:"17:00",vi:"Cập nhật kế hoạch khách hàng và nhật ký liên hệ trên CRM.",en:"Update the account plan and contact log in the CRM."}],mistakes:{vi:["Xác định bậc khối lượng trên sản lượng khách chưa cam kết bằng văn bản.","Chuyển toàn bộ mức tăng chỉ số nguyên liệu vào giá thay vì tỷ lệ chuyển giá đã thỏa thuận.","Chia sẻ thông tin giá, sản lượng của khách hàng khác để chốt nhanh hợp đồng."],en:["Setting the volume tier on volume the client has not committed in writing.","Passing the full raw-material increase into price instead of the agreed pass-through rate.","Sharing another client's prices or volumes to close a deal faster."]},career:[{vi:"Chuyên viên kinh doanh B2B",en:"B2B sales executive"},{vi:"Chuyên viên quản trị khách hàng chiến lược (KAM)",en:"Key Account Manager"},{vi:"Quản lý khách hàng chiến lược cấp cao",en:"Senior or global key account manager"},{vi:"Giám đốc khách hàng chiến lược",en:"Head of strategic accounts"}],glossary:[{term:"Account plan",vi:"Kế hoạch khách hàng: mục tiêu, sơ đồ quan hệ, cơ hội và hành động cho một khách chiến lược.",en:"Goals, relationship map, opportunities and actions for one strategic client."},{term:"QBR",vi:"Họp đánh giá kinh doanh hằng quý giữa nhà cung cấp và khách hàng.",en:"Quarterly business review between supplier and client."},{term:"OTIF",vi:"Tỷ lệ đơn hàng giao đúng hạn và đủ số lượng.",en:"Share of orders delivered on time and in full."},{term:"Index-linked pricing",vi:"Cơ chế điều chỉnh giá theo biến động chỉ số nguyên liệu đã thỏa thuận.",en:"Price adjustment tied to an agreed raw-material index."},{term:"Pass-through rate",vi:"Tỷ lệ chuyển giá: phần biến động chi phí nguyên liệu được phản ánh vào giá bán.",en:"The share of a raw-material cost change reflected in the selling price."}],quiz:[{q:{vi:"Giá cơ sở 5000 đồng, chỉ số nguyên liệu tăng 10%, tỷ lệ chuyển giá 60%, không chiết khấu. Giá mới là bao nhiêu?",en:"Base price 5000 VND, raw-material index up 10%, pass-through 60%, no discount. What is the new price?"},options:{vi:["5500 đồng","5050 đồng","5600 đồng","5300 đồng"],en:["5500 VND","5050 VND","5600 VND","5300 VND"]},answer:3,explain:{vi:"5000 x (1 + 0,6 x 10%) = 5000 x 1,06 = 5300 đồng.",en:"5000 x (1 + 0.6 x 10%) = 5000 x 1.06 = 5300 VND."}},{q:{vi:"Theo Luật Thương mại 2005, mức phạt vi phạm hợp đồng thông thường tối đa là bao nhiêu?",en:"Under the Commercial Law 2005, what is the usual maximum contractual penalty?"},options:{vi:["5% giá trị hợp đồng","8% giá trị phần nghĩa vụ bị vi phạm","10% giá trị hợp đồng","Không giới hạn"],en:["5% of contract value","8% of the breached obligation","10% of contract value","No limit"]},answer:1,explain:{vi:"Mức phạt do các bên thỏa thuận nhưng không quá 8% giá trị phần nghĩa vụ bị vi phạm, trừ trường hợp luật có quy định riêng.",en:"The parties agree the penalty but it may not exceed 8% of the breached obligation, unless a special rule applies."}},{q:{vi:"Người mua đề nghị bạn gửi bảng giá đang bán cho đối thủ của họ để tham chiếu. Bạn làm gì?",en:"A buyer asks for the prices you charge their competitor as a benchmark. What do you do?"},options:{vi:["Từ chối, báo cấp trên và đề xuất tham chiếu hợp lệ như chỉ số công khai","Gửi bản đã xóa tên khách hàng","Đọc qua điện thoại để không để lại dấu vết","Gửi nếu họ ký thỏa thuận bảo mật"],en:["Refuse, escalate and offer a lawful benchmark such as a public index","Send it with the client name removed","Read it out by phone to leave no trace","Send it if they sign an NDA"]},answer:0,explain:{vi:"Giá của khách hàng khác là bí mật kinh doanh được bảo vệ; tiết lộ vi phạm hợp đồng và làm mất niềm tin.",en:"Other clients' prices are protected trade secrets; disclosure breaches contracts and destroys trust."}},{q:{vi:"Khách xác nhận 2,4 triệu thùng, thêm 0,8 triệu đang chờ duyệt. Bậc khối lượng nên tính theo khối lượng nào?",en:"The client confirmed 2.4 million cartons with 0.8 million pending approval. Which volume should set the tier?"},options:{vi:["3,2 triệu vì sớm muộn sẽ có","Trung bình 2,8 triệu","2,4 triệu đã cam kết; phần chờ duyệt đưa vào điều khoản xem xét lại","0,8 triệu của dòng mới"],en:["3.2 million as it will come eventually","An average of 2.8 million","The committed 2.4 million; put the pending part in a review clause","The new line's 0.8 million"]},answer:2,explain:{vi:"Chiết khấu bậc phải dựa trên cam kết có căn cứ; khối lượng chưa chắc chắn xử lý bằng điều khoản điều chỉnh khi có thư cam kết.",en:"Tier discounts must rest on firm commitments; uncertain volume is handled by a review clause once committed."}}],tools_en:["CRM system","Pricing model spreadsheet","Customer profitability BI","ERP order processing system","Supplier collaboration portal"]}}})})(window.KKR);
